export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = inputs.gravity;
  const apexTime = launchSpeed / gravity;
  const apexHeight = (launchSpeed * launchSpeed) / (2 * gravity);

  // Time from the top is the simulation time minus apexTime, but since timeline displayOffset is -apexTime, time passed to evaluate represents 'time from the top' or we can just use time directly as elapsed time from launch if timeline start is 0.
  // Wait, the plan timeline starts at 0 and duration is 1.666, displayOffset is -apexTime. So time is elapsed from start (0 to duration). Let's define t as time.
  const t = time;

  const tossedVelocity = launchSpeed - gravity * t;
  const tossedHeight = launchSpeed * t - 0.5 * gravity * t * t;
  const tossedAcceleration = -gravity;

  let dropVelocity = 0;
  let dropAcceleration = 0;
  let dropHeight = apexHeight;

  if (t >= apexTime) {
    const dt = t - apexTime;
    dropVelocity = -gravity * dt;
    dropAcceleration = -gravity;
    dropHeight = apexHeight - 0.5 * gravity * dt * dt;
  }

  // State detection
  let tossState = "At launch";
  if (t > 0.05 && t < apexTime - 0.05) tossState = "Rising";
  else if (Math.abs(t - apexTime) <= 0.05) tossState = "At the top";
  else if (t > apexTime + 0.05 && tossedHeight > 0.05) tossState = "Falling";
  else if (t >= apexTime && tossedHeight <= 0.05) tossState = "At launch height";

  let dropState = "Held in place";
  if (Math.abs(t - apexTime) <= 0.05) dropState = "Just released";
  else if (t > apexTime + 0.05 && dropHeight > 0.05) dropState = "Falling together";
  else if (t > apexTime && dropHeight <= 0.05) dropState = "At launch height";

  // Drawing coordinates: height 0 to 2.2 m mapped to y pixels
  // Frame height 420. Lanes from y=60 to y=380 (height = 320 px)
  // 0 m at y=340, 2.2 m at y=80
  const hMin = 0;
  const hMax = 2.2;
  const yBottom = 340;
  const yTop = 80;
  const scaleY = (yBottom - yTop) / (hMax - hMin);

  function heightToY(h) {
    return yBottom - h * scaleY;
  }

  const laneW = 280;
  const tossX = 50;
  const dropX = 350;

  const objects = [];

  // Lanes
  objects.push(sdk.panel({ x: tossX, y: 50, w: laneW, h: 330, title: "Toss lane", state: tossState, id: "lane.toss" }));
  objects.push(sdk.panel({ x: dropX, y: 50, w: laneW, h: 330, title: "Drop lane", state: dropState, id: "lane.drop" }));

  // Axes inside lanes
  objects.push(sdk.axis("axis.toss", { x: tossX + 40, y: yBottom, length: yBottom - yTop, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));
  objects.push(sdk.axis("axis.drop", { x: dropX + 40, y: yBottom, length: yBottom - yTop, orientation: "y", min: 0, max: 2.2, label: "Height", unit: "m" }));

  // Ground marks
  objects.push(sdk.groundMark("mark.toss", tossX + laneW / 2, yBottom, 100, "0 m"));
  objects.push(sdk.groundMark("mark.drop", dropX + laneW / 2, yBottom, 100, "0 m"));

  // Gate at apex height
  const apexY = heightToY(apexHeight);
  const gateOpen = t >= apexTime;
  objects.push(sdk.gate("gate", dropX + laneW / 2, apexY, { open: gateOpen, w: 50, label: "Gate" }));

  // Balls
  const tossBallY = heightToY(Math.max(0, tossedHeight));
  const dropBallY = heightToY(Math.max(0, dropHeight));

  objects.push(sdk.circle("ball.toss", tossX + laneW / 2 - 30, tossBallY, 24, { role: "output" }));
  objects.push(sdk.circle("ball.drop", dropX + laneW / 2 - 30, dropBallY, 24, { role: "output" }));

  // Vectors (velocity and acceleration)
  // scale: 1 m/s -> 15 px
  const vScale = 15;
  objects.push(...sdk.vector("vec.v.toss", { x: tossX + laneW / 2 - 5, y: tossBallY }, { value: tossedVelocity, direction: "up" }, { scale: vScale, label: "v" }));
  objects.push(...sdk.vector("vec.a.toss", { x: tossX + laneW / 2 + 25, y: tossBallY }, { value: tossedAcceleration, direction: "up" }, { scale: vScale, label: "a", role: "prediction" }));

  objects.push(...sdk.vector("vec.v.drop", { x: dropX + laneW / 2 - 5, y: dropBallY }, { value: dropVelocity, direction: "up" }, { scale: vScale, label: "v" }));
  objects.push(...sdk.vector("vec.a.drop", { x: dropX + laneW / 2 + 25, y: dropBallY }, { value: dropAcceleration, direction: "up" }, { scale: vScale, label: "a", role: "prediction" }));

  // Callouts
  objects.push(...sdk.callout(tossX + laneW / 2 + 45, tossBallY - 20, [
    "v: " + sdk.format(tossedVelocity, 2) + " m/s",
    "a: " + sdk.format(tossedAcceleration, 2) + " m/s^2"
  ], { id: "callout.toss" }));

  objects.push(...sdk.callout(dropX + laneW / 2 + 45, dropBallY - 20, [
    "v: " + sdk.format(dropVelocity, 2) + " m/s",
    "a: " + sdk.format(dropAcceleration, 2) + " m/s^2"
  ], { id: "callout.drop" }));

  return {
    frame: sdk.frame(objects, { width: 640, height: 420 }),
    quantities: {
      tossedVelocity,
      tossedAcceleration,
      dropVelocity,
      dropAcceleration
    }
  };
}
